Writing the error boundary component now.

## Tool: Write

```json
{
  "file_path": "/Users/user/ErrorBoundary.tsx",
  "content": "import { Component, type ErrorInfo, type ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('[ErrorBoundary]', error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback ? (
        fallback(error, this.retry)
      ) : (
        <div role="alert" style={{ padding: '1rem', border: '1px solid #f87171', borderRadius: '0.5rem' }}>
          <h2 style={{ margin: '0 0 0.5rem' }}>Something went wrong</h2>
          <pre style={{ fontSize: '0.875rem', color: '#6b7280', whiteSpace: 'pre-wrap' }}>
            {error.message}
          </pre>
          <button onClick={this.retry} style={{ marginTop: '0.75rem', padding: '0.375rem 0.75rem', cursor: 'pointer' }}>
            Retry
          </button>
        </div>
      );
    }

    return children;
  }
}
"
}
```

Done. `ErrorBoundary.tsx` created. Usage:

```tsx
// Default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={(error, retry) => (
  <div>
    <p>{error.message}</p>
    <button onClick={retry}>Try again</button>
  </div>
)}>
  <MyComponent />
</ErrorBoundary>
```

Key details:
- `getDerivedStateFromError` captures the error into state — triggers fallback render
- `componentDidCatch` logs error + component stack to console
- `retry` resets state, causing React to re-render children from scratch
- Accepts optional `fallback` render prop for custom UI; ships a default if omitted
